import{_ as t,o as d,c as o,a2 as l}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"ダウンロードマネージャー & オフラインライブラリ","description":"ファイル命名規則、並列キュー制御、フォルダ自動振り分け、オフライン DB スキーマ","frontmatter":{"title":"ダウンロードマネージャー & オフラインライブラリ","description":"ファイル命名規則、並列キュー制御、フォルダ自動振り分け、オフライン DB スキーマ"},"headers":[],"relativePath":"features/downloads.md","filePath":"features/downloads.md","lastUpdated":1786168778000}'),a={name:"features/downloads.md"};function i(c,e,n,r,s,u){return d(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="ダウンロードマネージャー-オフラインライブラリ" tabindex="-1">ダウンロードマネージャー &amp; オフラインライブラリ <a class="header-anchor" href="#ダウンロードマネージャー-オフラインライブラリ" aria-label="Permalink to &quot;ダウンロードマネージャー &amp; オフラインライブラリ&quot;">​</a></h1><p>作品のダウンロード保存、キュー管理、およびオフラインライブラリの技術仕様です。</p><hr><h2 id="保存ルール-ファイル命名規則-downloadnaming-kt" tabindex="-1">保存ルール &amp; ファイル命名規則 (<code>DownloadNaming.kt</code>) <a class="header-anchor" href="#保存ルール-ファイル命名規則-downloadnaming-kt" aria-label="Permalink to &quot;保存ルール &amp; ファイル命名規則 (`DownloadNaming.kt`)&quot;">​</a></h2><p><code>AppSettings</code> の設定に基づいて、保存先のディレクトリ構造とファイル名が動的に生成されます。</p><h3 id="_1-フォルダ分類オプション" tabindex="-1">1. フォルダ分類オプション <a class="header-anchor" href="#_1-フォルダ分類オプション" aria-label="Permalink to &quot;1. フォルダ分類オプション&quot;">​</a></h3><ul><li><code>downloadFolderByArtist</code>: 有効時、<code>Pictures/Palleria/{artist_name}_{artist_id}/</code> 形式で作者別フォルダを作成。</li><li><code>downloadFolderByWork</code>: 有効時、上記の中に <code>{illust_id}_{title}/</code> 形式で作品別サブフォルダを作成。</li></ul><h3 id="_2-トークン置換パターン" tabindex="-1">2. トークン置換パターン <a class="header-anchor" href="#_2-トークン置換パターン" aria-label="Permalink to &quot;2. トークン置換パターン&quot;">​</a></h3><p>ファイル名フォーマット設定において利用可能な変数パターンの一覧です。</p><table tabindex="0"><thead><tr><th style="text-align:left;">トークン</th><th style="text-align:left;">置換される値</th><th style="text-align:left;">例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>{illust_id}</code></td><td style="text-align:left;">作品 ID</td><td style="text-align:left;"><code>12345678</code></td></tr><tr><td style="text-align:left;"><code>{title}</code></td><td style="text-align:left;">作品タイトル</td><td style="text-align:left;"><code>夏空イラスト</code></td></tr><tr><td style="text-align:left;"><code>{artist}</code></td><td style="text-align:left;">作者の表示名</td><td style="text-align:left;"><code>ゆんふぃ</code></td></tr><tr><td style="text-align:left;"><code>{artist_id}</code></td><td style="text-align:left;">作者の Pixiv ID</td><td style="text-align:left;"><code>987654</code></td></tr><tr><td style="text-align:left;"><code>{page}</code></td><td style="text-align:left;">ページ番号 (0 始まりまたは 1 始まり)</td><td style="text-align:left;"><code>p0</code></td></tr><tr><td style="text-align:left;"><code>{ext}</code></td><td style="text-align:left;">ファイル拡張子</td><td style="text-align:left;"><code>jpg</code> / <code>png</code> / <code>gif</code></td></tr></tbody></table><hr><h2 id="ダウンロードキュー制御-downloadqueuescreen" tabindex="-1">ダウンロードキュー制御 (<code>DownloadQueueScreen</code>) <a class="header-anchor" href="#ダウンロードキュー制御-downloadqueuescreen" aria-label="Permalink to &quot;ダウンロードキュー制御 (`DownloadQueueScreen`)&quot;">​</a></h2><p>ダウンロードタスクはバックグラウンドサービスおよび非同期 Coroutine チャネルで管理されます。</p><ul><li><code>simultaneousDownloads</code>: 同時並行ダウンロード数の上限設定（設定値: <code>1</code> 〜 <code>5</code>）。</li><li><code>offlineWifiOnly</code>: 有効時、Wi-Fi ネットワーク接続時のみキューの消化を実行。</li><li><strong>エラーリトライ</strong>: 通信一時断や 5xx エラーが発生した場合、指数バックオフで最大 3 回まで再試行。</li></ul><hr><h2 id="オフラインライブラリ-room-db-スキーマ" tabindex="-1">オフラインライブラリ Room DB スキーマ <a class="header-anchor" href="#オフラインライブラリ-room-db-スキーマ" aria-label="Permalink to &quot;オフラインライブラリ Room DB スキーマ&quot;">​</a></h2><p>ダウンロード完了した作品メタデータおよびローカルファイルパスは Room データベースで保存管理されます。</p><h3 id="_1-savedillustentity-作品エンティティ" tabindex="-1">1. <code>SavedIllustEntity</code> (作品エンティティ) <a class="header-anchor" href="#_1-savedillustentity-作品エンティティ" aria-label="Permalink to &quot;1. `SavedIllustEntity` (作品エンティティ)&quot;">​</a></h3><ul><li><code>illustId</code> (<code>Long</code>, PK): 作品 ID</li><li><code>title</code> (<code>String</code>): タイトル</li><li><code>userId</code> (<code>Long</code>): 作者 ID</li><li><code>userName</code> (<code>String</code>): 作者名</li><li><code>savedAt</code> (<code>Long</code>): 保存日時タイムスタンプ</li><li><code>pageCount</code> (<code>Int</code>): 総ページ数</li></ul><h3 id="_2-savedillustpageentity-ページエンティティ" tabindex="-1">2. <code>SavedIllustPageEntity</code> (ページエンティティ) <a class="header-anchor" href="#_2-savedillustpageentity-ページエンティティ" aria-label="Permalink to &quot;2. `SavedIllustPageEntity` (ページエンティティ)&quot;">​</a></h3><ul><li><code>id</code> (<code>Long</code>, PK Auto): ページ ID</li><li><code>illustId</code> (<code>Long</code>, FK): 対応する作品 ID</li><li><code>pageIndex</code> (<code>Int</code>): ページインデックス</li><li><code>localFilePath</code> (<code>String</code>): 端末内のローカルファイルパス (<code>file:///...</code>)</li><li><code>originalUrl</code> (<code>String</code>): 元の原寸画像 URL</li></ul><h3 id="_3-savedillustwithpages-リレーション" tabindex="-1">3. <code>SavedIllustWithPages</code> (リレーション) <a class="header-anchor" href="#_3-savedillustwithpages-リレーション" aria-label="Permalink to &quot;3. `SavedIllustWithPages` (リレーション)&quot;">​</a></h3><p><code>@Relation</code> アノテーションにより <code>SavedIllustEntity</code> と複数の <code>SavedIllustPageEntity</code> を 1 対多で結合取得し、オフライン環境 (<code>OfflineLibraryScreen</code>) での完全ローカル閲覧を実現。</p>',23)])])}const f=t(a,[["render",i]]);export{g as __pageData,f as default};
